try:
    n = int("4")
    print(10 / n)
except ZeroDivisionError:
    print("cannot divide by zero")
except ValueError:
    print("not a number")
else:
    print("no error happened")
finally:
    print("this always runs")

def safe_div(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None

print(safe_div(10, 2))
print(safe_div(10, 0))

try:
    print(1 / 0)
except ZeroDivisionError as exc:
    print("caught:", exc)
finally:
    print("cleanup done")

