def safe_int(text):
    try:
        return int(text)
    except ValueError:
        return 0

print(safe_int('12'))
print(safe_int('abc'))

examples.code:
def set_age(age):
    if age < 0:
        raise ValueError("age cannot be negative")
    return age

print(set_age(30))
try:
    set_age(-5)
except ValueError as exc:
    print("rejected:", exc)

def average(nums):
    assert nums, "the list must not be empty"
    return sum(nums) / len(nums)

print(average([2, 4, 6]))
try:
    average([])
except AssertionError as exc:
    print("assert failed:", exc)

for bad in [lambda: [1, 2][5], lambda: {"a": 1}["b"], lambda: "1" + 1]:
    try:
        bad()
    except Exception as exc:
        print(type(exc).__name__)

