exercises.solution:
def shout(text):
    if not text.strip():
        raise ValueError("empty text")
    return text.upper() + "!"

examples.code:
class InsufficientFunds(Exception):
    pass

def withdraw(balance, amount):
    if amount > balance:
        raise InsufficientFunds(f"need {amount - balance} more")
    return balance - amount

print(withdraw(100, 30))
try:
    withdraw(100, 150)
except InsufficientFunds as exc:
    print("blocked:", exc)

def parse(text):
    try:
        return int(text)
    except ValueError as exc:
        raise ValueError(f"bad number: {text!r}") from exc

try:
    parse("abc")
except ValueError as exc:
    print(exc)
    print("caused by:", type(exc.__cause__).__name__)

